ruleBookInfo.init:
@js:
(function(){
  try{ if(book){ book.type=32; book.originType=32; } }catch(e){}
  var d = JSON.parse(result);
  var data = (d && d.data) || {};
  var bu = String(baseUrl || (book&&book.bookUrl) || '');
  var t = bu.indexOf('t=audio') >= 0 ? 'audio' : 'text';
  var __o = {
    name: data.title || '',
    author: data.author || '',
    coverUrl: data.cover || '',
    intro: data.intro || '',
    kind: data.kind || '',
    tocUrl: data.tocUrl ? (data.tocUrl.indexOf('http') === 0 ? data.tocUrl : 'https://shuqi.neeao.dpdns.org' + data.tocUrl) : ''
  };
  return JSON.stringify(__o);
})()

ruleToc.chapterList:
@js:
(function(){
  var d = JSON.parse(result);
  var data = (d && d.data) || {};
  var arr = data.chapters || [];
  var out = [];
  for (var i=0;i<arr.length;i++){
    var it = arr[i] || {};
    var u = it.url || '';
    if (!u) continue;
    if (u.indexOf('http') !== 0) u = 'https://shuqi.neeao.dpdns.org' + u;
    out.push({ name: it.name || '', url: u });
  }
  return out;
})()

